<script setup lang="ts">
import { computed, ref } from 'vue'
import RIcon from './RIcon.vue'
defineProps<{ scene: number }>()
const emit = defineEmits<{ navigate: [id: number]; notify: [text: string] }>()
const selected = ref(0)
const folder = ref(0)
const evidence = ref(0)
const mode = ref('编辑')
const boardTab = ref(0)
const inspector = ref(0)
const zoom = ref(100)
const grid = ref(true)
const snap = ref(true)
const boundary = ref(false)
const noteText = ref('缓存更新失败通常发生在删除、更新或写入缓存的环节，需要结合日志和调用链，定位是缓存操作失败，还是后续流程处理异常。')
const rows = [
  ['缓存更新失败时\n怎样定位', '缓存', '3', 'v4', '今天'],
  ['分布式锁的边界', '分布式', '2', 'v2', '昨天'],
  ['JVM 内存模型速记', 'JVM', '1', 'v3', '11.08'],
  ['对账任务失败之后', '系统设计', '2', 'v1', '11.06'],
]
const evidenceRows = computed(() => [
  ['独立复练 · 11.10', '先确认删除结果，再判断是否需要补偿', '固定版本', 'file-text', 'teal'],
  ['项目事实 · 11.06', '参与排查，未主导方案', '固定版本', 'file-text', 'blue'],
  ['面后回忆 · 11.09', '记得提到恢复判据', '回忆记录', 'message-square', 'amber'],
].filter((_, i) => evidence.value === 0 || evidence.value - 1 === i))
const selectedTool = ref(0)
const boardNodes = ref([
  { x: 133, y: 404, w: 121, h: 100, label: '客户端', icon: 'monitor' },
  { x: 310, y: 404, w: 121, h: 100, label: 'API 网关', icon: 'network' },
  { x: 488, y: 404, w: 121, h: 100, label: '订单服务', icon: 'server' },
  { x: 666, y: 404, w: 121, h: 100, label: '奖励服务', icon: 'gift' },
  { x: 843, y: 404, w: 121, h: 100, label: '消息队列', icon: 'bar-chart-3' },
  { x: 497, y: 613, w: 138, h: 98, label: '预算服务', icon: 'database' },
  { x: 770, y: 613, w: 138, h: 98, label: '对账任务', icon: 'clock' },
])
const boardSvg = ref<SVGSVGElement>()
const boardConnectors = computed(() => {
  const nodes = boardNodes.value
  const order = nodes[2]!
  const queue = nodes[4]!
  const budget = nodes[5]!
  const reconciliation = nodes[6]!
  const queueRight = queue.x + queue.w
  const reconciliationRight = reconciliation.x + reconciliation.w
  const bottomY = reconciliation.y + 46
  return {
    main: nodes.slice(0, 4).map((node, index) => {
      const target = nodes[index + 1]!
      return `M${node.x + node.w + 2} ${node.y + 49}L${target.x - 6} ${target.y + 49}`
    }),
    compensation: [
      `M${queueRight} ${queue.y + 49}h14q20 0 20 25V${bottomY - 34}q0 34-32 34H${reconciliationRight + 4}`,
      `M${reconciliation.x} ${bottomY}L${budget.x + budget.w + 5} ${budget.y + 46}`,
      `M${budget.x - 3} ${budget.y + 46}H432`,
    ],
    event: `M${order.x + 60} ${order.y + order.h + 2}L${budget.x + 51} ${budget.y - 6}`,
  }
})
let dragging: { index: number; pointerId: number; x: number; y: number; originX: number; originY: number } | undefined
function boardPoint(event: PointerEvent) {
  const svg = boardSvg.value
  const matrix = svg?.getScreenCTM()
  if (!svg || !matrix) return
  const point = svg.createSVGPoint()
  point.x = event.clientX
  point.y = event.clientY
  return point.matrixTransform(matrix.inverse())
}
function startDrag(event: PointerEvent, index: number) {
  if (event.button !== 0) return
  const point = boardPoint(event)
  if (!point) return
  dragging = { index, pointerId: event.pointerId, x: point.x, y: point.y, originX: boardNodes.value[index]!.x, originY: boardNodes.value[index]!.y }
  ;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)
}
function drag(event: PointerEvent) {
  if (!dragging || event.pointerId !== dragging.pointerId) return
  const point = boardPoint(event)
  if (!point) return
  const node = boardNodes.value[dragging.index]!
  const x = dragging.originX + point.x - dragging.x
  const y = dragging.originY + point.y - dragging.y
  // 连线始终取节点位置；使用 SVG 坐标避免画布与窄屏缩放后指针错位。
  node.x = Math.max(100, Math.min(1035 - node.w, snap.value ? Math.round(x / 10) * 10 : x))
  node.y = Math.max(220, Math.min(880 - node.h, snap.value ? Math.round(y / 10) * 10 : y))
}
function endDrag(event: PointerEvent) {
  if (dragging?.pointerId !== event.pointerId) return
  const element = event.currentTarget as HTMLElement
  if (element.hasPointerCapture(event.pointerId)) element.releasePointerCapture(event.pointerId)
  dragging = undefined
}
</script>
